SELECT count(DISTINCT p.asset_id) AS n_total_assets
FROM v_programs p JOIN assets a USING (asset_id)
WHERE p.condition_key = 'D057092' AND NOT a.is_combo;

SELECT p.asset_id, a.canonical_name, p.max_phase_ever, p.n_active_trials, p.n_trials
FROM v_programs p JOIN assets a USING (asset_id)
WHERE p.condition_key = 'D057092' AND NOT a.is_combo AND p.max_phase_ever = 4.0;
